import csv,json
from pathlib import Path
P=Path('/home/psk6950/miniworld-engine-scratch/sol_inference_20261005/trimul')
metrics={'gpu__time_duration.sum':'ncu_duration_us','sm__throughput.avg.pct_of_peak_sustained_elapsed':'sm_pct','dram__throughput.avg.pct_of_peak_sustained_elapsed':'dram_pct','sm__pipe_tensor_cycles_active.avg.pct_of_peak_sustained_elapsed':'tensor_pct'}
duration_to_us={'ns':0.001,'nsecond':0.001,'nanosecond':0.001,'us':1.,'µs':1.,'μs':1.,'usecond':1.,'microsecond':1.,'ms':1000.,'msecond':1000.,'millisecond':1000.,'s':1e6,'second':1e6}
rows=[];agg=[]
for shard in ['0','1','2']:
 p=P/f'guarded_ncu_{shard}_raw.csv'
 if not p.exists():continue
 rr=list(csv.DictReader(p.open()));unit=rr.pop(0)
 timing=P/f'guarded_timing_{shard}.json'
 expected=[r for r in json.loads(timing.read_text()) if r['status']=='ok'];off=0
 for case in expected:
  D,H,L=case['D'],case['H'],case['L'];bidir=case['variant']=='bidirectional'
  count=(4+(bidir and L>512)) if D==128 else (4+(D>128)*2+int(bidir)) if D!=512 else (24 if bidir else 21)
  group=rr[off:off+count]
  assert len(group)==count,(shard,case['key'],off,len(rr))
  if D!=512:
   assert 'pack_kernel' in group[0]['Kernel Name'],(case['key'],group[0]['Kernel Name'])
   assert 'k3' in group[-1]['Kernel Name'],(case['key'],group[-1]['Kernel Name'])
  else:
   assert 'fwd_vec' in group[0]['Kernel Name'],(case['key'],group[0]['Kernel Name'])
   assert 'binary_kernel' in group[-1]['Kernel Name'],(case['key'],group[-1]['Kernel Name'])
  ks=[]
  for i,r in enumerate(group):
   k={'key':case['key'],'index':i,'kernel_name':r['Kernel Name'],'shard':shard,'ncu_id':r['ID']}
   for m,name in metrics.items():
    v=float(r[m].replace(',',''))
    if name=='ncu_duration_us':
     assert unit[m] in duration_to_us,('unknown NCU duration unit',unit[m])
     k[name]=v*duration_to_us[unit[m]]
    else:
     assert unit[m]=='%',('unknown NCU percentage unit',unit[m])
     k[name]=v
   ks.append(k);rows.append(k)
  total=sum(k['ncu_duration_us'] for k in ks)
  ag={'key':case['key'],'ncu_kernel_count':count,'ncu_kernel_sum_us':total}
  for name in ['sm_pct','dram_pct','tensor_pct']:
   ag['ncu_weighted_'+name]=sum(k['ncu_duration_us']*k[name] for k in ks)/total
  ag['ncu_weighted_max_sm_dram_pct']=sum(k['ncu_duration_us']*max(k['sm_pct'],k['dram_pct']) for k in ks)/total
  agg.append(ag);off+=count
 assert off==len(rr),(shard,off,len(rr))
(P/'ncu_summary.json').write_text(json.dumps(agg,indent=2))
for name,data in [('ncu_kernels.csv',rows),('ncu_summary.csv',agg)]:
 if data:
  with (P/name).open('w') as f:
   w=csv.DictWriter(f,fieldnames=list(data[0]));w.writeheader();w.writerows(data)
print('NCUcases',len(agg),'kernels',len(rows))

