import ast, csv, json, tempfile
from collections import Counter
from pathlib import Path
root=Path('/home/psk6950/miniworld-engine-scratch/sol_inference_20261005/apb')
old=json.loads((root/'results.before-unit-audit.json').read_text())['rows']
new=json.loads((root/'results.json').read_text())['rows']
count=Counter()
for a,b in zip(old,new,strict=True):
    for k,v in a.items():
        if k!='ncu': assert v==b[k], (k,v,b[k])
    for ka,kb in zip(a['ncu'],b['ncu'],strict=True):
        assert ka=={k:v for k,v in kb.items() if k!='duration_source_unit'}
    count.update({b['ncu'][0]['duration_source_unit']:1})
assert sum(count.values())==30 and dict(count)=={'ns':30}
# Exercise parser conversion and unknown-unit rejection using isolated synthetic CSVs.
node=next(n for n in ast.parse((root/'report.py').read_text()).body if isinstance(n,ast.FunctionDef) and n.name=='ncu')
namespace={'csv':csv}; exec(compile(ast.Module(body=[node],type_ignores=[]),'ncu_parser','exec'),namespace)
fields=['ID','Process ID','Kernel Name','gpu__time_duration.sum','sm__throughput.avg.pct_of_peak_sustained_elapsed','dram__throughput.avg.pct_of_peak_sustained_elapsed','sm__pipe_tensor_cycles_active.avg.pct_of_peak_sustained_elapsed']
with tempfile.TemporaryDirectory() as tmp:
    path=Path(tmp)/'synthetic.csv'
    def write(unit):
        with path.open('w') as f:
            w=csv.writer(f,quoting=csv.QUOTE_ALL); w.writerow(fields); w.writerow(['','','',unit,'%','%','%']); w.writerow([0,1,'test',2,10,20,30])
    for unit,factor in {'nsecond':1,'ns':1,'usecond':1e3,'us':1e3,'µs':1e3,'msecond':1e6,'ms':1e6,'second':1e9,'s':1e9}.items():
        write(unit); assert namespace['ncu'](path)[0]['time_ns']==2*factor
    write('fortnight')
    try: namespace['ncu'](path)
    except AssertionError: pass
    else: raise AssertionError('Unknown unit accepted')
audit={'raw_ncu_files':30,'duration_units':dict(count),'kernel_records':sum(len(r['ncu']) for r in new),'numeric_results_unchanged':True,'conversion_cases_passed':9,'unknown_unit_rejected':True,'benchmark_ms_unit_asserted':True}
(root/'unit_audit.json').write_text(json.dumps(audit,indent=2)+'\n'); print(json.dumps(audit))
